  margin-bottom: 20px;
  border: 1px solid #ddd;
  border-radius: 5px;
}
```

```javascript
const form = document.getElementById('registration-form');

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = document.getElementById('name');
  const email = document.getElementById('email');
  const phone = document.getElementById('phone');

  if (name.value && email.value && phone.value) {
    const data = {
      name: name.value,
      email: email.value,
      phone: phone.value
    }
    console.log(data); // Here you can send the data to the server or do what you need with it.
    form.reset(); // Reset the form after successful submission
  }
});
```

Please note that this is a very basic example. You might want to add more fields, add validation, better responsiveness, and handle server-side interactions for real user registration.

You might also want to use a JavaScript library like jQuery or a framework like React or Angular to handle more complex interactions.

Remember, for real user registration or any other user data, you should handle the data on the server side and implement security measures.
